import{_ as t,o as s,c as r,a6 as a}from"./chunks/framework.BHBQfcoO.js";const p=JSON.parse('{"title":"Users & Devices","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/users-devices.md","filePath":"configuration/users-devices.md"}'),i={name:"configuration/users-devices.md"};function o(n,e,d,l,c,h){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="users-devices" tabindex="-1">Users &amp; Devices <a class="header-anchor" href="#users-devices" aria-label="Permalink to &quot;Users &amp; Devices&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Preview feature</p><p>The <strong>Users &amp; Devices</strong> tab requires the LCARdS HA integration (v2026.3.0+) with the <code>scoped_storage</code> capability. If the integration is absent or on an older version, the tab is hidden.</p></div><p>The <strong>Users &amp; Devices</strong> tab in the <a href="./">LCARdS Config Panel</a> is the central place to view and manage the devices and users that have stored per-device or per-user setting overrides.</p><p>It has three sections. Non-admin users see only <strong>Current Session</strong>. HA admins see all three.</p><hr><h2 id="current-session" tabindex="-1">Current Session <a class="header-anchor" href="#current-session" aria-label="Permalink to &quot;Current Session&quot;">​</a></h2><p>Shows the identity of the current browser session: this is your <strong>device record</strong> as seen by LCARdS.</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Device name</strong></td><td>Human-readable label for this browser. Editable by any user: click the edit icon, type a new name, and save. Also settable via the URL parameter <code>?lcards_device=My%20Tablet</code> on first visit.</td></tr><tr><td><strong>Device ID</strong></td><td>Stable UUID stored in this browser&#39;s <code>localStorage</code>. Persists across page reloads and HA logins from the same browser profile.</td></tr><tr><td><strong>Last seen</strong></td><td>Timestamp of this device&#39;s last heartbeat to the backend.</td></tr><tr><td><strong>User agent</strong></td><td>Browser/OS string recorded at last registration.</td></tr></tbody></table><p>Setting a device name is optional but makes it much easier to identify sessions in the Devices list and when using <a href="./../architecture/internals/ha-services.html">targeted HA services</a>.</p><hr><h2 id="users-admin-only" tabindex="-1">Users <em>(admin only)</em> <a class="header-anchor" href="#users-admin-only" aria-label="Permalink to &quot;Users *(admin only)*&quot;">​</a></h2><p>Lists every HA user who has at least one stored per-user override. For each entry you can see:</p><ul><li>The HA display name (resolved from the HA auth list)</li><li>The opaque HA user ID</li><li>A <strong>Clear overrides</strong> action: removes all per-user scoped settings for that user, reverting them to Device → Global fallback</li></ul><blockquote><p>Clearing overrides does not affect the user&#39;s device records or any global settings.</p></blockquote><hr><h2 id="devices-admin-only" tabindex="-1">Devices <em>(admin only)</em> <a class="header-anchor" href="#devices-admin-only" aria-label="Permalink to &quot;Devices *(admin only)*&quot;">​</a></h2><p>Lists every device that has ever registered a heartbeat with the LCARdS backend. For each device:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Display name: click the edit (pencil) icon to rename inline</td></tr><tr><td><strong>Last seen</strong></td><td>ISO timestamp of the last heartbeat</td></tr><tr><td><strong>Device ID</strong></td><td>Stable UUID for targeting services</td></tr><tr><td><strong>Delete</strong></td><td>Removes the entire device record from the backend (requires confirmation). Any scoped overrides stored for this device are also deleted.</td></tr></tbody></table><p>Deleting a device does not prevent it from re-registering: if the browser visits the dashboard again it will create a new record with the same UUID.</p><hr><h2 id="how-scoped-settings-work" tabindex="-1">How scoped settings work <a class="header-anchor" href="#how-scoped-settings-work" aria-label="Permalink to &quot;How scoped settings work&quot;">​</a></h2><p>LCARdS settings (currently: sound scheme, per-event sound overrides) are resolved in this order, using the first non-null value found:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Device scope  →  User scope  →  Global scope  →  HA helper fallback</span></span></code></pre></div><ul><li><strong>Device</strong> overrides apply to any HA user logged in on that specific browser.</li><li><strong>User</strong> overrides apply to a specific HA user regardless of which device they use.</li><li><strong>Global</strong> is the installation-wide default, shared by everyone.</li></ul><p>Per-user and per-device overrides are configured in the individual feature tabs (e.g. <a href="./../core/sounds.html">Sound</a> → <em>Per-User / Per-Device Overrides</em> section). The <strong>Users &amp; Devices</strong> tab is the admin view for managing <em>existing</em> records; it does not expose raw setting values.</p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./sounds.html">Sounds</a>: configure per-user/device sound overrides</li><li><a href="./">Configuration overview</a>: panel setup and all tabs overview</li><li><a href="./../architecture/internals/ha-services.html">HA Services: targeting</a>: use device/user IDs in <code>lcards.*</code> service calls</li><li><a href="./../architecture/subsystems/scoped-settings.html">Scoped Settings Service</a>: developer reference for the underlying storage system</li></ul>',28)])])}const v=t(i,[["render",o]]);export{p as __pageData,v as default};
